package potion

import (
	"context"
	"math"
	"os"
	"reflect"
	"testing"
)

// TestPublishedModelCompatibility compares the Go pipeline with fixed output
// generated by model2vec 0.5.0 and Hugging Face tokenizers. Set
// POTION_TEST_MODEL_DIR to a local checkout of the published model to run it.
func TestPublishedModelCompatibility(t *testing.T) {
	dir := os.Getenv("POTION_TEST_MODEL_DIR")
	if dir == "" {
		t.Skip("POTION_TEST_MODEL_DIR is not set")
	}
	model, err := OpenFromDir(dir)
	if err != nil {
		t.Fatal(err)
	}

	tokenCases := []struct {
		text string
		want []int
	}{
		{text: "Hello, world!", want: []int{6595, 13, 1091, 2}},
		{text: `func main() { println("hello") }`, want: []int{29527, 1367, 9, 10, 66, 29544, 9, 3, 6595, 3, 10, 68}},
		{text: "你好世界", want: []int{41734, 44362, 748, 45639}},
		{text: "HTTPServer::Serve", want: []int{37314, 27, 27, 2713}},
		{text: "CamelCase snake_case 123", want: []int{33665, 6491, 38, 1556, 12141}},
		{text: "unknown 😀 token", want: []int{3245, 18207}},
		{text: "[PAD]", want: []int{0}},
		{text: "[pad]", want: []int{0}},
		{text: "[PÁD]", want: []int{0}},
		{text: "[UNK]", want: nil},
		{text: "hello [UNK] world", want: []int{6595, 1091}},
		{text: " [PAD] ", want: []int{0}},
		{text: "[PAD]foo", want: []int{34, 10690, 36, 28382}},
		{text: "foo[PAD]", want: []int{28382, 34, 10690, 36}},
		{text: "foo [PAD]bar", want: []int{28382, 34, 10690, 36, 2350}},
		{text: "foo [PAD] bar", want: []int{28382, 0, 2350}},
		{text: "([PAD])", want: []int{9, 0, 10}},
		{text: "[PAD][PAD]", want: []int{0, 0}},
		{text: "_[PAD]", want: []int{38, 34, 10690, 36}},
		{text: "  hello  world  ", want: []int{6595, 1091}},
		{text: "HELLO\tWORLD", want: []int{6595, 1091}},
		{text: "é É", want: []int{44, 44}},
		{text: "e\u0301", want: []int{44}},
		{text: "\u0301hello", want: []int{6595}},
		{text: "café", want: []int{6671}},
		{text: "\u00a0hello\u00a0", want: []int{6595}},
		{text: "\u2003hello\u2003", want: []int{6595}},
		{text: "\u0085hello\u0085", want: []int{6595}},
		{text: "\u2028hello\u2028", want: []int{6595}},
		{text: "\u200bhello\u200b", want: []int{6595}},
		{text: "\x00hello\ufffd", want: []int{6595}},
		{text: "a\x01b", want: []int{10116}},
		{text: "a\ufeffb", want: []int{10116}},
		{text: "foo😀bar", want: nil},
		{text: "你好\t世界", want: []int{41734, 44362, 748, 45639}},
		{text: "foo/bar.baz", want: []int{28382, 16, 2350, 15, 32436}},
		{text: "snake_case", want: []int{6491, 38, 1556}},
		{text: "", want: nil},
	}
	for _, tokenCase := range tokenCases {
		ids, err := model.tokenIDs(tokenCase.text)
		if err != nil {
			t.Fatalf("tokenize %q: %v", tokenCase.text, err)
		}
		if !reflect.DeepEqual(ids, tokenCase.want) {
			t.Errorf("token IDs for %q = %v, want %v", tokenCase.text, ids, tokenCase.want)
		}
	}

	got, err := model.EmbedOne(context.Background(), "Hello, world!")
	if err != nil {
		t.Fatal(err)
	}
	want := []float32{
		0.12658691, -0.0033473969, 0.10668945, -0.16931152, 0.096069336, 0.079040527, 0.086425781, 0.092529297,
		-0.18737793, -0.064819336, 0.054443359, 0.062042236, 0.16564941, -0.11590576, -0.044647217, -0.073425293,
		0.070373535, 0.048187256, -0.15100098, -0.10412598, 0.067260742, 0.10040283, 0.10760498, 0.098144531,
		-0.016891479, -0.060852051, 0.052764893, -0.12432861, 0.024765015, 0.11181641, -0.033660889, -0.013191223,
		0.030075073, 0.02947998, 0.03793335, 0.09954834, -0.017166138, 0.048370361, -0.074951172, -0.1574707,
		-0.045227051, 0.051971436, -0.048828125, 0.046813965, 0.054168701, 0.054016113, -0.020263672, 0.1137085,
		0.0060195923, 0.090148926, 0.1171875, -0.084655762, 0.029983521, -0.0098571777, -0.07611084, -0.087585449,
		0.12438965, -0.058166504, 0.028427124, 0.051208496, -0.029907227, 0.052612305, 0.089294434, -0.021774292,
		-0.015899658, 0.05670166, 0.062103271, 0.0013427734, -0.019668579, -0.040802002, -0.03213501, -0.059417725,
		-0.014816284, 0.064147949, 0.10290527, 0.013412476, -0.081542969, 0.022064209, -0.019134521, -0.056915283,
		0.040863037, 0.020828247, 0.044799805, 0.042877197, 0.040679932, -0.019927979, -0.12139893, -0.011314392,
		-0.019515991, 0.10809326, 0.081726074, -0.088012695, 0.017150879, 0.0020980835, -0.062561035, 0.0087738037,
		-0.014686584, 0.017791748, 0.0703125, -0.016952515, -0.012763977, 0.045715332, -0.084289551, -0.0031642914,
		-0.12359619, 0.013725281, -0.086914062, 0.010421753, -0.12310791, -0.033660889, -0.011138916, -0.13684082,
		-0.050170898, 0.019760132, -0.050170898, -0.12139893, -0.086547852, -0.037689209, 0.017547607, -0.105896,
		0.026123047, -0.033691406, -0.071533203, -0.052307129, 0.02822876, 0.096374512, 0.042297363, 0.031890869,
		0.0011615753, -0.039886475, -0.081359863, -0.048400879, -0.05859375, -0.009437561, -0.00028419495, 0.081481934,
		0.03527832, -0.012458801, 0.044586182, 0.0017623901, 0.058654785, -0.082763672, -0.010452271, 0.034240723,
		0.059051514, -0.028549194, 0.0065956116, 0.020568848, 0.017333984, -0.10632324, -0.060913086, 0.057098389,
		-0.023635864, -0.0074577332, 0.025878906, -0.01260376, 0.013801575, -0.09576416, -0.054595947, -0.039855957,
		-0.045593262, -0.055114746, -0.023223877, 0.11151123, 0.044158936, 0.068664551, 0.065856934, 0.0051269531,
		0.063781738, -0.065673828, 0.064208984, 0.038360596, -0.046508789, -0.045349121, 0.059204102, 0.013336182,
		-0.043334961, 0.0042762756, -0.071411133, -0.024200439, -0.074035645, 0.0047340393, 0.0021286011, 0.0013790131,
		0.057556152, -0.058197021, -0.022766113, -0.021713257, 0.037780762, 0.057617188, -0.10028076, 0.039245605,
		0.0077323914, 0.038146973, -0.031280518, -0.022857666, 0.044647217, 0.08795166, 0.011146545, -0.041351318,
		-0.032318115, -0.0070800781, 0.042541504, -0.011817932, -0.026657104, -0.085144043, 0.045196533, -0.034759521,
		-0.079711914, 0.11212158, -0.0074424744, -0.011138916, -0.038787842, -0.036499023, 0.088500977, 0.046051025,
		0.0015859604, 0.01751709, -0.04977417, 0.056915283, 0.042755127, 0.11138916, 0.064025879, -0.039733887,
		-0.030654907, -0.018722534, -0.0055809021, 0.10943604, 0.069274902, -0.013961792, 0.017929077, -0.026748657,
		-0.0069007874, -0.034973145, -0.039031982, 0.00274086, 0.072387695, 0.010749817, -0.04574585, 0.074035645,
		-0.018417358, -0.02293396, 0.020675659, 0.019683838, -0.0037307739, 0.0045585632, 0.051086426, -0.004940033,
		0.084350586, 0.080871582, -0.019607544, 0.016204834, -0.062164307, -0.065124512, -0.10290527, 0.0035915375,
	}
	if len(got) != len(want) {
		t.Fatalf("vector dimension = %d, want %d", len(got), len(want))
	}
	for i := range want {
		if math.Abs(float64(got[i]-want[i])) > 2e-4 {
			t.Fatalf("vector[%d] = %v, want %v", i, got[i], want[i])
		}
	}
}
